// Built-in background audio. Per the project's guidance this contains no
// melodic instruments: daf rhythms (generated by tools/generate-tones.mjs,
// `generated: true`) and, when added, vocal-only nasheeds.

export const MUSIC_LIBRARY = [
  {
    id: 'daf-zaffa',
    title: 'Daf & Claps',
    description: 'Upbeat zaffa rhythm on the daf with hand claps.',
    instruments: 'Daf · Claps',
    kind: 'daf',
    generated: true
  },
  {
    id: 'daf-gentle',
    title: 'Gentle Daf',
    description: 'A soft, calm daf rhythm. No claps.',
    instruments: 'Daf',
    kind: 'daf',
    generated: true
  },
  {
    id: 'daf-festive',
    title: 'Festive Daf',
    description: 'A lively celebration rhythm with ring jingles and claps.',
    instruments: 'Daf · Claps',
    kind: 'daf',
    generated: true
  }
];

export const LIBRARY_IDS = MUSIC_LIBRARY.map((t) => t.id);

export function libraryTrack(id) {
  return MUSIC_LIBRARY.find((t) => t.id === id) || null;
}

export function libraryPath(id) {
  return `audio/library/${id}.mp3`;
}

export function libraryAssetId(id) {
  return `library-${id}`;
}
